<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
use ForumIntelligence\Bootstrap\Services;
use ForumIntelligence\Domain\Failure;
final class ConfigurationConsentTest extends TestCase {
 private Services $services;private ForumIntelligence\Admin\Admin $admin;private int $actor;private mixed $settings;private object $missing;private array $hooks;private array $budget;private array $outage;private string $circuit;
 protected function setUp():void{
  global $wp_filter;$this->hooks=array_map(static fn(WP_Hook $h):WP_Hook=>clone $h,$wp_filter);$this->missing=new stdClass();$this->settings=get_option('fi_settings',$this->missing);update_option('fi_settings',['ai_enabled'=>false]);add_filter('pre_wp_mail',static fn()=>true);$this->actor=(int)wp_insert_user(['user_login'=>'fi_consent99_'.bin2hex(random_bytes(8)),'user_pass'=>'owned-only','role'=>'administrator']);self::assertGreaterThan(0,$this->actor);bbp_set_user_role($this->actor,bbp_get_keymaster_role());wp_set_current_user($this->actor);$this->services=new Services();$this->services->register();$frontend=new ForumIntelligence\Frontend\Frontend($this->services->operations,$this->services->solutions,$this->services->access,dirname(__DIR__,2).'/forum-intelligence-for-bbpress.php');$this->admin=new ForumIntelligence\Admin\Admin($this->services,$frontend);$this->admin->register();$s=$this->services->store;$this->budget=$s->rows("SELECT * FROM {$s->table('limits')} WHERE bucket=%s",[hash('sha256','0:ai_daily')]);$endpoint=defined('FI_AI_ENDPOINT')?(string)constant('FI_AI_ENDPOINT'):'https://api.openai.com/v1';$this->circuit='fi_ai_outage_'.substr(hash('sha256',$endpoint),0,16);$this->outage=[get_option('_transient_'.$this->circuit,$this->missing),get_option('_transient_timeout_'.$this->circuit,$this->missing)];delete_transient($this->circuit);
 }
 protected function tearDown():void{
  $s=$this->services->store;$s->execute("DELETE FROM {$s->table('limits')} WHERE bucket=%s",[hash('sha256','0:ai_daily')]);foreach($this->budget as $row)$s->execute("INSERT INTO {$s->table('limits')} (bucket,window_start,count) VALUES (%s,%d,%d)",[$row['bucket'],$row['window_start'],$row['count']]);foreach(['_transient_'.$this->circuit,'_transient_timeout_'.$this->circuit]as $i=>$key){if($this->outage[$i]===$this->missing)delete_option($key);else update_option($key,$this->outage[$i]);}if($this->settings===$this->missing)delete_option('fi_settings');else update_option('fi_settings',$this->settings);require_once ABSPATH.'wp-admin/includes/user.php';$user=get_userdata($this->actor);if($user&&!str_starts_with($user->user_login,'fi_consent99_'))throw new RuntimeException('Refusing foreign consent actor');wp_delete_user($this->actor);wp_set_current_user(0);global $wp_filter;$wp_filter=$this->hooks;
 }
 public function testMalformedTruthyConfigurationCannotTurnOnAiOrSemanticProcessing():void{
  foreach(['false','off','true','yes',[false],2]as $value){$clean=$this->admin->sanitize(['ai_enabled'=>$value,'semantic'=>$value]);self::assertFalse($clean['ai_enabled'],'Only an explicit checkbox/boolean choice may enable external processing.');self::assertFalse($clean['semantic']);}
 }
 public function testReviewedJsonFalseStringCannotBecomeExternalConsent():void{
  $this->services->operations->execute('config_import',['reviewed'=>true,'json'=>wp_json_encode(['version'=>1,'settings'=>['ai_enabled'=>'false','semantic'=>'false']])],$this->actor);self::assertFalse(get_option('fi_settings')['ai_enabled']);self::assertFalse(get_option('fi_settings')['semantic']);
 }
 private function noTransport(mixed $flag,bool $embedding):void{
  update_option('fi_settings',['ai_enabled'=>$flag,'ai_daily_requests'=>10000]);$calls=0;$mock=static function($pre,array $args,string $url)use(&$calls,$embedding){$calls++;return['headers'=>[],'response'=>['code'=>200,'message'=>'OK'],'body'=>wp_json_encode($embedding?['data'=>[['embedding'=>[0.1,0.2]]]]:['choices'=>[['message'=>['content'=>wp_json_encode(['answer'=>'Owned mock answer','source_ids'=>[1]])]]]])];};add_filter('pre_http_request',$mock,99,3);$refused=false;try{$provider=new ForumIntelligence\Infrastructure\AI\OpenAICompatible($this->services->store);try{if($embedding)$provider->embed('Owned public mock evidence');else$provider->generate('Owned mock question',[['id'=>1,'text'=>'Owned public mock evidence']]);}catch(Failure $failure){$refused=true;self::assertSame(503,$failure->status);}}finally{remove_filter('pre_http_request',$mock,99);}self::assertTrue($refused,'Malformed stored flags must refuse before a transport request.');self::assertSame(0,$calls);
 }
 public function testStoredTextConsentMustBeABooleanBeforeAnyNativeHttpRequest():void{foreach(['false','off','true','yes',[false],1,'1',2,null,false]as $flag)$this->noTransport($flag,false);}
 public function testStoredEmbeddingConsentMustBeABooleanBeforeAnyNativeHttpRequest():void{foreach(['false','off','true','yes',[false],1,'1',2,null,false]as $flag)$this->noTransport($flag,true);}
 public function testCanonicalNativeCheckboxesStillEnableReviewedSettings():void{foreach([true,1,'1']as $flag){$clean=$this->admin->sanitize(['ai_enabled'=>$flag,'semantic'=>$flag]);self::assertTrue($clean['ai_enabled']);self::assertTrue($clean['semantic']);}foreach([false,0,'0','',null,[]]as $flag){$clean=$this->admin->sanitize(['ai_enabled'=>$flag,'semantic'=>$flag]);self::assertFalse($clean['ai_enabled']);self::assertFalse($clean['semantic']);}}
 public function testConsentRevokedDuringNativeBudgetClaimCannotReachTransport():void{
  update_option('fi_settings',['ai_enabled'=>true,'ai_daily_requests'=>10000]);$calls=0;$changed=false;$sqlFilter=function(string $sql)use(&$changed):string{if(!$changed&&str_contains($sql,'fi_limits')&&str_starts_with($sql,'INSERT INTO')){$changed=true;update_option('fi_settings',['ai_enabled'=>false,'ai_daily_requests'=>10000]);}return$sql;};$http=static function($pre)use(&$calls){$calls++;return['headers'=>[],'response'=>['code'=>200,'message'=>'OK'],'body'=>wp_json_encode(['choices'=>[['message'=>['content'=>wp_json_encode(['answer'=>'Owned mock answer','source_ids'=>[1]])]]]])];};add_filter('query',$sqlFilter,99);add_filter('pre_http_request',$http,99);$refused=false;try{try{(new ForumIntelligence\Infrastructure\AI\OpenAICompatible($this->services->store))->generate('Owned mock question',[['id'=>1,'text'=>'Owned public mock evidence']]);}catch(Failure $failure){$refused=true;self::assertSame(503,$failure->status);}}finally{remove_filter('query',$sqlFilter,99);remove_filter('pre_http_request',$http,99);}self::assertTrue($changed);self::assertTrue($refused,'Consent must be renewed after the real native budget query.');self::assertSame(0,$calls);
 }

 public function testMalformedStoredSemanticFlagCannotInvokeEmbeddingProvider():void{
  $local=new class implements ForumIntelligence\Contracts\SearchEngine{public function search(string $q,array $f,int $u):array{return['items'=>[],'has_more'=>false,'page'=>1];}};$provider=new class implements ForumIntelligence\Contracts\EmbeddingProvider{public int $calls=0;public function embed(string $text):array{$this->calls++;return[0.1,0.2];}};$vectors=new ForumIntelligence\Infrastructure\Search\LocalVectorStore($this->services->store);$hybrid=new ForumIntelligence\Infrastructure\Search\HybridSearch($local,$provider,$vectors,$this->services->access,$this->services->solutions,$this->services->store);
  foreach(['false','off','true','yes',[false],1,'1',2,null,false]as $flag){update_option('fi_settings',['ai_enabled'=>true,'semantic'=>$flag]);$hybrid->search('Owned native semantic question',[],$this->actor);self::assertSame(0,$provider->calls,'Malformed stored semantic flags must use the ordinary lexical path.');}
 }

 public function testProviderLoggingModesRetainQuotasWithoutRecordingContent():void{
  $s=$this->services->store;$table=$s->table('metrics');$kinds=['ai_requests','ai_tokens','ai_failed'];$saved=$s->rows("SELECT * FROM $table WHERE kind IN (%s,%s,%s)",$kinds);$failed=false;$calls=0;$lastBody='';
  $http=static function($pre,array $args)use(&$failed,&$calls,&$lastBody){++$calls;$lastBody=$args['body'];if($failed)return new WP_Error('owned_transport_failure','Owned failure');return['headers'=>[],'body'=>wp_json_encode(['choices'=>[['message'=>['content'=>wp_json_encode(['answer'=>'Owned response','source_ids'=>[1]])]]],'usage'=>['total_tokens'=>17]]),'response'=>['code'=>200,'message'=>'OK'],'cookies'=>[]];};add_filter('pre_http_request',$http,99,2);
  try{
   foreach([['usage',[1,17,1]],['errors',[0,0,1]],['off',[0,0,0]],[['usage'],[0,0,0]],['unknown',[0,0,0]]]as[$mode,$expected]){
    $s->execute("DELETE FROM $table WHERE kind IN (%s,%s,%s)",$kinds);delete_transient($this->circuit);update_option('fi_settings',['ai_enabled'=>true,'ai_logging'=>$mode,'ai_daily_requests'=>10000]);$failed=false;$provider=new ForumIntelligence\Infrastructure\AI\OpenAICompatible($s);self::assertSame('Owned response',$provider->generate('OWNED_LOGGING_QUERY_CANARY',[['id'=>1,'text'=>'OWNED_LOGGING_SOURCE_CANARY']])['answer']);$failed=true;
    try{$provider->generate('OWNED_LOGGING_QUERY_CANARY',[['id'=>1,'text'=>'OWNED_LOGGING_SOURCE_CANARY']]);self::fail('Expected intercepted native transport failure.');}catch(Failure $failure){self::assertSame(503,$failure->status);}
    foreach($kinds as $i=>$kind){$row=$s->row("SELECT COALESCE(SUM(count),0) AS total FROM $table WHERE kind=%s",[$kind]);self::assertSame($expected[$i],(int)$row['total']);}
    self::assertStringNotContainsString('OWNED_LOGGING_QUERY_CANARY',wp_json_encode($s->rows("SELECT * FROM $table WHERE kind IN (%s,%s,%s)",$kinds)));
   }
   self::assertSame(10,$calls);$budget=$s->row("SELECT SUM(count) AS total FROM {$s->table('limits')} WHERE bucket=%s",[hash('sha256','0:ai_daily')]);self::assertGreaterThanOrEqual(10,(int)$budget['total']);self::assertStringContainsString('OWNED_LOGGING_SOURCE_CANARY',$lastBody);
   foreach(['usage','errors','off']as$mode)self::assertSame($mode,$this->admin->sanitize(['ai_logging'=>$mode])['ai_logging']);foreach([['usage'],'debug',true,1]as$invalid)self::assertSame('off',$this->admin->sanitize(['ai_logging'=>$invalid])['ai_logging']);
  }finally{remove_filter('pre_http_request',$http,99);$s->execute("DELETE FROM $table WHERE kind IN (%s,%s,%s)",$kinds);foreach($saved as$row)$s->execute("INSERT INTO $table (day,kind,count) VALUES (%s,%s,%d)",[$row['day'],$row['kind'],$row['count']]);}
 }

}
